CustomField.formula:
IF(
    /* Step 1, determine the user type for the online calculator when Lender is National Funding */
    OR(
        CONTAINS(Lender_ID__r.Name, 'National Funding'),
        CONTAINS(Lender_ID__r.Name, 'Quick Bridge')
    ), IF(
        /* Step 2, determine if renewals */
        CONTAINS(TEXT(Opportunity__r.Type), 'RENEWAL'), 'Renewal',
        IF(
            /* Step 3, determine if Broker */
            OR(Opportunity__r.RecordType.DeveloperName = 'Broker_WC_Oppty', Opportunity__r.RecordType.DeveloperName = 'Broker_FRPSA'), 'Broker',
            IF(
                /* Step 3, determine if Direct */
               OR(Opportunity__r.RecordType.DeveloperName = 'MCA_Oppty', Opportunity__r.RecordType.DeveloperName = 'FRPSA'), 'Direct', 'Error' 
            )
        )
    ), 'External Lender'
 )
